/* empty css                                                                            */import{c as t,o as r,a1 as e}from"./chunks/framework.C0tRMDue.js";const n=e('<h1 id="projketuppgift-rbs-restaurangens-bestallningssystem" tabindex="-1">Projketuppgift rbs: Restaurangens beställningssystem <a class="header-anchor" href="#projketuppgift-rbs-restaurangens-bestallningssystem" aria-label="Permalink to &quot;Projketuppgift rbs: Restaurangens beställningssystem&quot;">​</a></h1><p>I denna uppgift ska du utveckla ett system för att hantera beställningar och menyval på en restaurang. Uppgiften består av tre nivåer där varje nivå bygger vidare på den tidigare.</p><h2 id="niva-for-betyg-e" tabindex="-1">Nivå för betyg E: <a class="header-anchor" href="#niva-for-betyg-e" aria-label="Permalink to &quot;Nivå för betyg E:&quot;">​</a></h2><p>Skapa klasserna <strong>MenuItem</strong>, <strong>Customer</strong> och <strong>Order</strong>.</p><ol><li><p>Klass <strong>MenuItem</strong></p><ul><li>Attribut: <ul><li><strong>name</strong> (namn på maträtten eller drycken)</li><li><strong>price</strong> (pris)</li></ul></li><li>Metoder: <ul><li><strong>__init__</strong> - Initierar namn och pris.</li><li><strong>__str__</strong> - Returnerar en beskrivning av menyalternativet, t.ex. &quot;Pizza - 85 kr&quot;.</li></ul></li></ul></li><li><p>Klass <strong>Customer</strong></p><ul><li>Attribut: <ul><li>name (namn på kunden) Metoder:</li><li><strong>__init__</strong> - Tar emot kundens namn.</li><li><strong>__str__</strong> - Returnerar kundens namn.</li></ul></li></ul></li><li><p>Klass <strong>Order</strong></p><ul><li>Attribut: <ul><li><strong>menu_items</strong> - En lista över alla menyval som lagts till i beställningen.</li></ul></li><li>Metoder: <ul><li><strong>__init__</strong> - Skapar en tom lista för menyval.</li><li><strong>add_item</strong> - Lägger till ett MenuItem-objekt i beställningen.</li><li><strong>calculate_total</strong> - Beräknar och returnerar totala priset för beställningen.</li></ul></li></ul></li></ol><h2 id="niva-for-betyg-c" tabindex="-1">Nivå för betyg C: <a class="header-anchor" href="#niva-for-betyg-c" aria-label="Permalink to &quot;Nivå för betyg C:&quot;">​</a></h2><p>Utöka systemet med <strong>arv</strong>.</p><ol><li><p>Utöka MenuItem till en klasshierarki:</p><ul><li>Skapa subklasser <strong>Food</strong> och <strong>Beverage</strong> (Dryck) som ärver från <strong>MenuItem</strong>.</li><li><strong>Food</strong> har ett attribut <strong>calories</strong> för kaloriinnehåll.</li><li><strong>Beverage</strong> (Dryck) har ett attribut <strong>volume</strong> för volym i centiliter.</li><li>Använd <em>overloading</em> för att hantera olika attribut beroende på om det är mat eller dryck.</li></ul></li><li><p>Modifiera <strong>Order</strong>-klassen:</p><ul><li>Lägg till en metod <strong>remove_item</strong> för att ta bort ett menyval från beställningen.</li><li>Lägg till en metod <strong>show_order</strong> som visar alla valda artiklar.</li></ul></li></ol><h2 id="niva-for-betyg-a" tabindex="-1">Nivå för betyg A: <a class="header-anchor" href="#niva-for-betyg-a" aria-label="Permalink to &quot;Nivå för betyg A:&quot;">​</a></h2><p>Implementera abstrakta klasser, polymorfism och generiska klasser.</p><ol><li>Skapa en abstrakt klass <strong>RestaurantEntity</strong> som basklass för <strong>MenuItem</strong> och <strong>Customer</strong>. <ul><li><strong>RestaurantEntity</strong> ska ha en abstrakt metod <strong>get_info</strong> som varje subklass ska implementera.</li></ul></li><li>Använd polymorfism i <strong>Order</strong> för att hantera både mat och dryck på ett enhetligt sätt. <ul><li>Lägg till en metod <strong>order_summary</strong> som returnerar en sammanställning av beställningen med alla menyval.</li></ul></li><li>Implementera en generisk klass <strong>OrderContainer</strong> för att hantera en lista med olika <strong>RestaurantEntity</strong>-objekt.</li></ol>',11),a=[n],u=JSON.parse('{"title":"Projketuppgift rbs: Restaurangens beställningssystem","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"programming2/task/index.md","filePath":"programming2/task/index.md"}'),s={name:"programming2/task/index.md"},d=Object.assign(s,{setup(l){return(i,o)=>(r(),t("div",null,a))}});export{u as __pageData,d as default};
